{"path":"src/lib/time.ts","content":"export type TimeFormat = '12h' | '24h'
export type Mode = 'meeting' | 'base'

/** UTC offset in minutes for a timezone at a given instant (DST-aware, fractional-safe). */
export function getUtcOffsetMinutes(tz: string, date: Date = new Date()): number {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  })
  const parts: Record<string, number> = {}
  for (const p of dtf.formatToParts(date)) {
    if (p.type !== 'literal') parts[p.type] = Number(p.value)
  }
  // hour can be 24 in some engines at midnight
  const hour = parts.hour % 24
  const asUtc = Date.UTC(parts.year, parts.month - 1, parts.day, hour, parts.minute, parts.second)
  return Math.round((asUtc - Math.floor(date.getTime() / 1000) * 1000) / 60000)
}

export function formatUtcOffset(offsetMinutes: number): string {
  const sign = offsetMinutes >= 0 ? '+' : '-'
  const abs = Math.abs(offsetMinutes)
  const h = Math.floor(abs / 60)
  const m = abs % 60
  return m === 0 ? `UTC${sign}${h}` : `UTC${sign}${h}:${String(m).padStart(2, '0')}`
}

/** Local time (minutes since midnight, 0–1439) in a city when it is `refHour`:00 in the reference. */
export function localMinutes(refHour: number, cityOffset: number, refOffset: number): number {
  const v = refHour * 60 + (cityOffset - refOffset)
  return ((v % 1440) + 1440) % 1440
}

export function isAwake(localMins: number, wake: number, sleep: number): boolean {
  const w = wake * 60
  const s = sleep * 60
  if (w === s) return true // full-day window
  if (w < s) return localMins >= w && localMins < s
  return localMins >= w || localMins < s // overnight
}

export function formatTime(hour: number, minute: number, format: TimeFormat): string {
  const h = ((hour % 24) + 24) % 24
  if (format === '24h') {
    return `${String(h).padStart(2, '0')}:${String(minute).padStart(2, '0')}`
  }
  const suffix = h < 12 ? 'am' : 'pm'
  const h12 = h % 12 === 0 ? 12 : h % 12
  return minute === 0 ? `${h12}${suffix}` : `${h12}:${String(minute).padStart(2, '0')}${suffix}`
}

export function formatHour(hour: number, format: TimeFormat): string {
  return formatTime(hour, 0, format)
}

export function formatLocalMinutes(mins: number, format: TimeFormat): string {
  return formatTime(Math.floor(mins / 60), mins % 60, format)
}

/** Group sorted hours (0–23) into linear contiguous ranges: [start, endExclusive]. */
export function hoursToRanges(hours: number[]): Array<[number, number]> {
  const sorted = [...hours].sort((a, b) => a - b)
  const ranges: Array<[number, number]> = []
  for (const h of sorted) {
    const last = ranges[ranges.length - 1]
    if (last && h === last[1]) last[1] = h + 1
    else ranges.push([h, h + 1])
  }
  return ranges
}

export function formatRanges(hours: number[], format: TimeFormat): string[] {
  return hoursToRanges(hours).map(
    ([start, end]) => `${formatHour(start, format)} — ${formatHour(end, format)}`,
  )
}

export function currentTimeInTz(tz: string, format: TimeFormat, now: Date = new Date()): string {
  try {
    return new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      hour: 'numeric',
      minute: '2-digit',
      hour12: format === '12h',
    }).format(now).replace(/\s?(AM|PM)/i, (m) => m.trim().toLowerCase())
  } catch {
    return ''
  }
}

/** Current hour (0–23) in a timezone. */
export function currentHourInTz(tz: string, now: Date = new Date()): number {
  const v = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: 'numeric', hour12: false }).format(now)
  return Number(v) % 24
}
"}

{"path":"src/hooks/useMediaQuery.ts","content":"import { useEffect, useState } from 'react'

export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState<boolean>(
    () => typeof window !== 'undefined' && window.matchMedia(query).matches,
  )
  useEffect(() => {
    const mql = window.matchMedia(query)
    const onChange = () => setMatches(mql.matches)
    onChange()
    mql.addEventListener('change', onChange)
    return () => mql.removeEventListener('change', onChange)
  }, [query])
  return matches
}
"}

{"path":"src/lib/storage.ts","content":"import { CITY_CATALOG, DEFAULT_CITY_IDS } from '../data/cities'
import type { Mode, TimeFormat } from './time'

export interface PersistedState {
  cityIds: string[]
  wake: number
  sleep: number
  format: TimeFormat
  mode: Mode
}

export const DEFAULT_STATE: PersistedState = {
  cityIds: [...DEFAULT_CITY_IDS],
  wake: 7,
  sleep: 23,
  format: '12h',
  mode: 'meeting',
}

const KEY = 'tz-overlap-state-v1'

export function loadState(): PersistedState {
  try {
    const raw = localStorage.getItem(KEY)
    if (!raw) return DEFAULT_STATE
    const parsed = JSON.parse(raw) as Partial<PersistedState>
    const validIds = new Set(CITY_CATALOG.map((c) => c.id))
    const cityIds = Array.isArray(parsed.cityIds)
      ? [...new Set(parsed.cityIds.filter((id) => typeof id === 'string' && validIds.has(id)))]
      : []
    const isHour = (v: unknown): v is number => typeof v === 'number' && v >= 0 && v <= 23 && Number.isInteger(v)
    return {
      cityIds: cityIds.length ? cityIds : [...DEFAULT_CITY_IDS],
      wake: isHour(parsed.wake) ? parsed.wake : 7,
      sleep: isHour(parsed.sleep) ? parsed.sleep : 23,
      format: parsed.format === '24h' ? '24h' : '12h',
      mode: parsed.mode === 'base' ? 'base' : 'meeting',
    }
  } catch {
    return DEFAULT_STATE
  }
}

export function saveState(state: PersistedState) {
  try {
    localStorage.setItem(KEY, JSON.stringify(state))
  } catch {
    // storage unavailable (private mode quotas etc.) — app still works in-memory
  }
}
"}

{"path":"src/components/CityPicker.tsx","content":"import { useMemo, useRef, useState } from 'react'
import { CITY_CATALOG, type City } from '../data/cities'
import { formatUtcOffset, getUtcOffsetMinutes } from '../lib/time'

interface Props {
  selectedIds: string[]
  onAdd: (id: string) => void
}

export default function CityPicker({ selectedIds, onAdd }: Props) {
  const [query, setQuery] = useState('')
  const [open, setOpen] = useState(false)
  const [highlight, setHighlight] = useState(0)
  const inputRef = useRef<HTMLInputElement>(null)

  const available = useMemo(() => {
    const q = query.trim().toLowerCase()
    return CITY_CATALOG.filter((c) => !selectedIds.includes(c.id)).filter(
      (c) => !q || c.name.toLowerCase().includes(q) || c.country.toLowerCase().includes(q) || c.region.toLowerCase().includes(q),
    )
  }, [query, selectedIds])

  const offsets = useMemo(() => {
    const map = new Map<string, string>()
    for (const c of CITY_CATALOG) map.set(c.id, formatUtcOffset(getUtcOffsetMinutes(c.tz)))
    return map
  }, [])

  function add(city: City) {
    onAdd(city.id)
    setQuery('')
    setHighlight(0)
    inputRef.current?.focus()
  }

  return (
    <div className="city-picker">
      <label className="picker-label" htmlFor="city-search">Add a city</label>
      <div className="picker-box">
        <input
          ref={inputRef}
          id="city-search"
          type="text"
          role="combobox"
          aria-expanded={open}
          aria-controls="city-listbox"
          aria-label="Search cities by name or country"
          placeholder="Search by city or country…"
          value={query}
          onChange={(e) => { setQuery(e.target.value); setOpen(true); setHighlight(0) }}
          onFocus={() => setOpen(true)}
          onBlur={() => window.setTimeout(() => setOpen(false), 120)}
          onKeyDown={(e) => {
            if (e.key === 'ArrowDown') { e.preventDefault(); setOpen(true); setHighlight((h) => Math.min(h + 1, available.length - 1)) }
            else if (e.key === 'ArrowUp') { e.preventDefault(); setHighlight((h) => Math.max(h - 1, 0)) }
            else if (e.key === 'Enter' && open && available[highlight]) { e.preventDefault(); add(available[highlight]) }
            else if (e.key === 'Escape') setOpen(false)
          }}
        />
        <span className="picker-count">{available.length} available</span>
      </div>
      {open && (
        <ul className="picker-list" id="city-listbox" role="listbox" aria-label="Available cities">
          {available.length === 0 && <li className="picker-empty">No cities match “{query}”.</li>}
          {available.map((city, i) => (
            <li key={city.id} role="option" aria-selected={i === highlight}>
              <button
                type="button"
                className={i === highlight ? 'picker-item highlighted' : 'picker-item'}
                onMouseDown={(e) => e.preventDefault()}
                onMouseEnter={() => setHighlight(i)}
                onClick={() => add(city)}
              >
                <span className="picker-city">{city.name}</span>
                <span className="picker-meta">{city.country} · {city.region}</span>
                <span className="picker-offset">{offsets.get(city.id)}</span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}
"}

{"path":"src/components/OverlapSummary.tsx","content":"import { formatRanges, type Mode, type TimeFormat } from '../lib/time'
import type { City } from '../data/cities'

interface Props {
  mode: Mode
  format: TimeFormat
  cities: City[]
  meetingHours: number[]
  baseHoursByCityId: Record<string, number[]>
}

function RangeBadges({ hours, format }: { hours: number[]; format: TimeFormat }) {
  return (
    <span className="badges">
      {formatRanges(hours, format).map((r) => (
        <span key={r} className="badge">{r}</span>
      ))}
    </span>
  )
}

export default function OverlapSummary({ mode, format, cities, meetingHours, baseHoursByCityId }: Props) {
  if (cities.length < 2) return null
  const ref = cities[0]

  if (mode === 'meeting') {
    return (
      <section className="summary" aria-label="Overlap summary">
        {meetingHours.length === 0 ? (
          <p className="summary-warn" role="alert">
            ⚠ No overlap — there is no hour when everyone in {cities.map((c) => c.name).join(', ')} is awake at the same time. Try widening the awake window.
          </p>
        ) : (
          <p className="summary-line">
            <strong>{meetingHours.length} {meetingHours.length === 1 ? 'hour' : 'hours'} of overlap</strong>
            <span className="summary-in"> in {ref.name} time:</span>{' '}
            <RangeBadges hours={meetingHours} format={format} />
          </p>
        )}
      </section>
    )
  }

  return (
    <section className="summary" aria-label="Overlap summary">
      <p className="summary-title">Overlap with {ref.name} (base), in {ref.name} time:</p>
      <ul className="summary-list">
        {cities.slice(1).map((city) => {
          const hours = baseHoursByCityId[city.id] ?? []
          return (
            <li key={city.id} className="summary-row">
              <span className="summary-city">{ref.name} ↔ {city.name}:</span>
              {hours.length === 0 ? (
                <span className="summary-warn-inline" role="alert">⚠ No overlap with {city.name}</span>
              ) : (
                <>
                  <strong>{hours.length} {hours.length === 1 ? 'hour' : 'hours'}</strong>{' '}
                  <RangeBadges hours={hours} format={format} />
                </>
              )}
            </li>
          )
        })}
      </ul>
    </section>
  )
}
"}

{"path":"src/lib/grid.ts","content":"import type { City } from '../data/cities'

export interface HourCell {
  refHour: number
  localMins: number
  label: string
  awake: boolean
  overlap: boolean
}

export interface EnrichedCity {
  city: City
  offsetMinutes: number
  offsetLabel: string
  currentTime: string
  isRef: boolean
  cells: HourCell[]
}

export function cellClass(cell: HourCell): string {
  if (cell.overlap) return 'cell overlap'
  if (cell.awake) return 'cell awake'
  return 'cell sleeping'
}

export function cellStateLabel(cell: HourCell): string {
  if (cell.overlap) return 'overlap'
  if (cell.awake) return 'awake'
  return 'sleeping'
}
"}

{"path":"src/components/DesktopGrid.tsx","content":"import type { EnrichedCity } from '../lib/grid'
import { cellClass, cellStateLabel } from '../lib/grid'
import { formatHour, type TimeFormat } from '../lib/time'

interface Props {
  cities: EnrichedCity[]
  format: TimeFormat
  nowHour: number | null
  onPromote: (id: string) => void
  onRemove: (id: string) => void
}

export default function DesktopGrid({ cities, format, nowHour, onPromote, onRemove }: Props) {
  const hours = Array.from({ length: 24 }, (_, i) => i)
  return (
    <div className="grid-wrap desktop-grid" data-layout="desktop">
      <table className="tz-table" aria-label="Timezone overlap grid">
        <thead>
          <tr>
            <th scope="col" className="city-col">City / reference hour →</th>
            {hours.map((h) => (
              <th key={h} scope="col" className={h === nowHour ? 'hour-head now' : 'hour-head'} title={h === nowHour ? 'Current hour in reference city' : undefined}>
                {formatHour(h, format)}
                {h === nowHour && <span className="now-dot" aria-label="now">●</span>}
              </th>
            ))}
            <th scope="col"><span className="sr-only">Remove</span></th>
          </tr>
        </thead>
        <tbody>
          {cities.map(({ city, offsetLabel, currentTime, isRef, cells }) => (
            <tr key={city.id} className={isRef ? 'city-row ref-row' : 'city-row'} data-city={city.name}>
              <th scope="row" className="city-cell">
                <button type="button" className="city-name" onClick={() => onPromote(city.id)} title={isRef ? 'Reference city' : `Make ${city.name} the reference city`} aria-label={isRef ? `${city.name}, reference city` : `Make ${city.name} the reference city`}>
                  {city.name}
                </button>
                {isRef && <span className="ref-badge">REF</span>}
                <span className="city-sub">{city.country}</span>
                <span className="city-meta">{offsetLabel} · {currentTime}</span>
              </th>
              {cells.map((cell) => (
                <td
                  key={cell.refHour}
                  className={`${cellClass(cell)}${cell.refHour === nowHour ? ' now-col' : ''}`}
                  data-state={cellStateLabel(cell)}
                  data-hour={cell.refHour}
                  title={`${city.name}: ${cell.label} — ${cellStateLabel(cell)}`}
                >
                  {cell.label}
                </td>
              ))}
              <td className="remove-cell">
                <button type="button" className="remove-btn" onClick={() => onRemove(city.id)} aria-label={`Remove ${city.name}`} title={`Remove ${city.name}`}>×</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}
"}

{"path":"src/components/MobileGrid.tsx","content":"import type { EnrichedCity } from '../lib/grid'
import { cellClass, cellStateLabel } from '../lib/grid'
import { formatHour, type TimeFormat } from '../lib/time'

interface Props {
  cities: EnrichedCity[]
  format: TimeFormat
  nowHour: number | null
  onPromote: (id: string) => void
  onRemove: (id: string) => void
}

export default function MobileGrid({ cities, format, nowHour, onPromote, onRemove }: Props) {
  const hours = Array.from({ length: 24 }, (_, i) => i)
  return (
    <div className="grid-wrap mobile-grid" data-layout="mobile">
      <table className="tz-table-vertical" aria-label="Timezone overlap grid">
        <thead>
          <tr>
            <th scope="col" className="hour-col">Ref hour</th>
            {cities.map(({ city, offsetLabel, currentTime, isRef }) => (
              <th key={city.id} scope="col" className={isRef ? 'mobile-city-head ref-col' : 'mobile-city-head'} data-city={city.name}>
                <button type="button" className="city-name" onClick={() => onPromote(city.id)} title={isRef ? 'Reference city' : `Make ${city.name} the reference city`} aria-label={isRef ? `${city.name}, reference city` : `Make ${city.name} the reference city`}>
                  {city.name}
                </button>
                {isRef && <span className="ref-badge">REF</span>}
                <span className="city-sub">{city.country}</span>
                <span className="city-meta">{offsetLabel}</span>
                <span className="city-meta">{currentTime}</span>
                <button type="button" className="remove-btn" onClick={() => onRemove(city.id)} aria-label={`Remove ${city.name}`} title={`Remove ${city.name}`}>×</button>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {hours.map((h) => (
            <tr key={h} className={h === nowHour ? 'hour-row now-row' : 'hour-row'}>
              <th scope="row" className="mobile-hour">{formatHour(h, format)}{h === nowHour ? ' ●' : ''}</th>
              {cities.map(({ city, cells }) => {
                const cell = cells[h]
                return (
                  <td
                    key={city.id}
                    className={cellClass(cell)}
                    data-state={cellStateLabel(cell)}
                    data-hour={h}
                    data-city={city.name}
                    title={`${city.name}: ${cell.label} — ${cellStateLabel(cell)}`}
                  >
                    {cell.label}
                  </td>
                )
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}
"}

{"path":"src/App.tsx","content":"import { useEffect, useMemo, useState } from 'react'
import { cityById } from './data/cities'
import { loadState, saveState } from './lib/storage'
import {
  currentHourInTz,
  currentTimeInTz,
  formatLocalMinutes,
  formatUtcOffset,
  getUtcOffsetMinutes,
  isAwake,
  localMinutes,
} from './lib/time'
import type { EnrichedCity } from './lib/grid'
import CityPicker from './components/CityPicker'
import DesktopGrid from './components/DesktopGrid'
import MobileGrid from './components/MobileGrid'
import OverlapSummary from './components/OverlapSummary'
import SettingsPanel from './components/SettingsPanel'
import { useMediaQuery } from './hooks/useMediaQuery'

export default function App() {
  const [initial] = useState(loadState)
  const [cityIds, setCityIds] = useState<string[]>(initial.cityIds)
  const [wake, setWake] = useState(initial.wake)
  const [sleep, setSleep] = useState(initial.sleep)
  const [format, setFormat] = useState(initial.format)
  const [mode, setMode] = useState(initial.mode)
  const [now, setNow] = useState(() => new Date())

  const isMobile = useMediaQuery('(max-width: 767px)')

  // keep clocks fresh
  useEffect(() => {
    const t = window.setInterval(() => setNow(new Date()), 30_000)
    return () => window.clearInterval(t)
  }, [])

  // persistence
  useEffect(() => {
    saveState({ cityIds, wake, sleep, format, mode })
  }, [cityIds, wake, sleep, format, mode])

  const cities = useMemo(
    () => cityIds.map(cityById).filter((c): c is NonNullable<typeof c> => Boolean(c)),
    [cityIds],
  )

  const { enriched, meetingHours, baseHoursByCityId, nowHour } = useMemo(() => {
    if (cities.length === 0) {
      return { enriched: [] as EnrichedCity[], meetingHours: [] as number[], baseHoursByCityId: {} as Record<string, number[]>, nowHour: null as number | null }
    }
    const ref = cities[0]
    const refOffset = getUtcOffsetMinutes(ref.tz, now)
    const offsets = cities.map((c) => getUtcOffsetMinutes(c.tz, now))

    // awake[cityIndex][refHour]
    const awake = cities.map((_, ci) =>
      Array.from({ length: 24 }, (_, h) => isAwake(localMinutes(h, offsets[ci], refOffset), wake, sleep)),
    )

    const meeting: number[] = []
    for (let h = 0; h < 24; h++) if (awake.every((row) => row[h])) meeting.push(h)
    const meetingSet = new Set(meeting)

    const baseById: Record<string, number[]> = {}
    cities.forEach((city, ci) => {
      const hours: number[] = []
      for (let h = 0; h < 24; h++) {
        if (ci === 0 ? awake[0][h] : awake[0][h] && awake[ci][h]) hours.push(h)
      }
      baseById[city.id] = hours
    })
    const baseSets: Record<string, Set<number>> = Object.fromEntries(
      Object.entries(baseById).map(([k, v]) => [k, new Set(v)]),
    )

    const rows: EnrichedCity[] = cities.map((city, ci) => ({
      city,
      offsetMinutes: offsets[ci],
      offsetLabel: formatUtcOffset(offsets[ci]),
      currentTime: currentTimeInTz(city.tz, format, now),
      isRef: ci === 0,
      cells: Array.from({ length: 24 }, (_, h) => {
        const mins = localMinutes(h, offsets[ci], refOffset)
        const overlap = mode === 'meeting' ? meetingSet.has(h) && awake[ci][h] : (baseSets[city.id]?.has(h) ?? false) && awake[ci][h]
        return { refHour: h, localMins: mins, label: formatLocalMinutes(mins, format), awake: awake[ci][h], overlap }
      }),
    }))

    return { enriched: rows, meetingHours: meeting, baseHoursByCityId: baseById, nowHour: currentHourInTz(ref.tz, now) }
  }, [cities, wake, sleep, format, mode, now])

  const refCity = cities[0]

  function addCity(id: string) {
    setCityIds((prev) => (prev.includes(id) ? prev : [...prev, id]))
  }
  function removeCity(id: string) {
    setCityIds((prev) => prev.filter((x) => x !== id))
  }
  function promoteCity(id: string) {
    setCityIds((prev) => (prev[0] === id ? prev : [id, ...prev.filter((x) => x !== id)]))
  }

  return (
    <div className="app">
      <header className="topbar">
        <div className="topbar-inner">
          <div>
            <h1>muse-wonder-full-1.0</h1>
            <p className="tagline">Timezone overlap checker — find the hours when your whole team is awake.</p>
          </div>
          <div className="mode-toggle" role="group" aria-label="Mode">
            <button type="button" className={mode === 'meeting' ? 'mode-btn active' : 'mode-btn'} aria-pressed={mode === 'meeting'} onClick={() => setMode('meeting')}>
              Meeting Mode
            </button>
            <button type="button" className={mode === 'base' ? 'mode-btn active' : 'mode-btn'} aria-pressed={mode === 'base'} onClick={() => setMode('base')}>
              Base Mode
            </button>
          </div>
        </div>
        <p className="mode-hint">
          {mode === 'meeting'
            ? 'Meeting Mode: one shared window when everyone across all cities is awake at once — for scheduling a group call.'
            : `Base Mode: each city is compared only against the base${refCity ? ` (${refCity.name})` : ''}, so every row can highlight a different window.`}
        </p>
      </header>

      <main className="main">
        <div className="controls">
          <SettingsPanel wake={wake} sleep={sleep} format={format} onWake={setWake} onSleep={setSleep} onFormat={setFormat} />
          <section className="panel add-panel" aria-label="Add city">
            <div className="panel-head">
              <h2>Cities</h2>
              <p>Click a city name to make it the reference. The first city anchors every calculation.</p>
            </div>
            <CityPicker selectedIds={cityIds} onAdd={addCity} />
            {cities.length > 0 && (
              <ul className="selected-list" aria-label="Selected cities">
                {cities.map((c, i) => (
                  <li key={c.id}>
                    <button type="button" className="chip-name" onClick={() => promoteCity(c.id)}>{c.name}</button>
                    {i === 0 && <span className="ref-badge">REF</span>}
                    <button type="button" className="chip-remove" onClick={() => removeCity(c.id)} aria-label={`Remove ${c.name}`}>×</button>
                  </li>
                ))}
              </ul>
            )}
          </section>
        </div>

        <OverlapSummary mode={mode} format={format} cities={cities} meetingHours={meetingHours} baseHoursByCityId={baseHoursByCityId} />

        {cities.length === 0 ? (
          <div className="empty">
            <p>No cities selected yet. Add a city above to start comparing timezones.</p>
          </div>
        ) : isMobile ? (
          <MobileGrid cities={enriched} format={format} nowHour={nowHour} onPromote={promoteCity} onRemove={removeCity} />
        ) : (
          <DesktopGrid cities={enriched} format={format} nowHour={nowHour} onPromote={promoteCity} onRemove={removeCity} />
        )}

        <footer className="legend" aria-label="Legend">
          <span className="legend-item"><span className="swatch overlap" /> Overlap</span>
          <span className="legend-item"><span className="swatch awake" /> Awake, no overlap</span>
          <span className="legend-item"><span className="swatch sleeping" /> Sleeping</span>
          <span className="hint">
            {mode === 'meeting'
              ? 'Green cells = everyone awake'
              : `Green cells = awake at the same time as ${refCity ? refCity.name : 'the base city'}`}
          </span>
          <span className="footnote">Offsets use today&apos;s date, so daylight saving is handled automatically. Hours are shown in {refCity ? refCity.name : 'reference'} time across the top{isMobile ? '/side' : ''}.</span>
        </footer>
      </main>
    </div>
  )
}
"}

{"path":"src/styles.css","content":":root {
  --ink: #1b2632;
  --ink-soft: #425364;
  --ink-faint: #7d8b99;
  --page: #e9edef;
  --panel: #ffffff;
  --line: #d3dbe0;
  --header-bg: #182430;
  --green: #159947;
  --green-dark: #0f7a38;
  --amber-bg: #fff4d6;
  --amber-line: #e3c25e;
  --amber-ink: #6d5200;
  --radius: 10px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--page);
  color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 15px;
  line-height: 1.45;
}
button, input, select { font: inherit; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

.topbar { background: var(--header-bg); color: #f2f5f7; border-bottom: 4px solid var(--green); }
.topbar-inner {
  max-width: 1280px; margin: 0 auto; padding: 22px 20px 6px;
  display: flex; justify-content: space-between; align-items: flex-end; gap: 20px; flex-wrap: wrap;
}
.topbar h1 {
  margin: 0; font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(26px, 4vw, 38px); font-weight: 700; letter-spacing: -0.5px; line-height: 1.1;
}
.tagline { margin: 6px 0 0; color: #b9c6d1; font-size: 15px; }
.mode-hint { max-width: 1280px; margin: 0 auto; padding: 8px 20px 18px; color: #9fb0bf; font-size: 13.5px; }
.mode-toggle { display: flex; border: 1px solid #3c4f62; border-radius: 999px; padding: 3px; background: #101922; }
.mode-btn {
  border: 0; background: transparent; color: #c4d2df; padding: 9px 18px; border-radius: 999px; cursor: pointer; font-weight: 600;
}
.mode-btn:hover { color: #fff; }
.mode-btn.active { background: var(--green); color: #fff; }
.mode-btn:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid #7fd6a0; outline-offset: 2px; }

.main { max-width: 1280px; margin: 0 auto; padding: 20px; display: flex; flex-direction: column; gap: 16px; }
.controls { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
@media (max-width: 860px) { .controls { grid-template-columns: 1fr; } }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px 18px; }
.panel-head h2 { margin: 0 0 4px; font-size: 16px; }
.panel-head p { margin: 0 0 12px; color: var(--ink-soft); font-size: 13.5px; }
.settings-grid { display: flex; flex-wrap: wrap; gap: 14px; align-items: end; }
.field { display: flex; flex-direction: column; gap: 6px; }
.field > span, .picker-label { font-size: 13px; font-weight: 700; color: var(--ink-soft); }
.field select {
  padding: 9px 10px; border: 1px solid var(--line); border-radius: 7px; background: #fff; min-width: 140px; color: var(--ink);
}
.seg { display: flex; border: 1px solid var(--line); border-radius: 7px; overflow: hidden; }
.seg-btn { border: 0; background: #fff; padding: 9px 16px; cursor: pointer; font-weight: 600; color: var(--ink-soft); }
.seg-btn.active { background: var(--ink); color: #fff; }
.awake-readout { margin: 0; color: var(--ink-soft); font-size: 14px; padding-bottom: 9px; }

.city-picker { position: relative; }
.picker-box { display: flex; align-items: center; gap: 10px; margin-top: 6px; }
.picker-box input {
  flex: 1; min-width: 0; padding: 10px 12px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink); background: #fff;
}
.picker-count { font-size: 12.5px; color: var(--ink-faint); white-space: nowrap; }
.picker-list {
  position: absolute; z-index: 30; left: 0; right: 0; top: calc(100% + 6px);
  margin: 0; padding: 6px; list-style: none; background: #fff; border: 1px solid var(--line); border-radius: 9px;
  box-shadow: 0 14px 34px rgba(24, 36, 48, 0.18); max-height: 300px; overflow: auto;
}
.picker-item {
  width: 100%; display: flex; align-items: baseline; gap: 10px; text-align: left;
  border: 0; background: transparent; padding: 9px 10px; border-radius: 6px; cursor: pointer; color: var(--ink);
}
.picker-item.highlighted { background: #e6f4ec; }
.picker-city { font-weight: 700; }
.picker-meta { flex: 1; color: var(--ink-faint); font-size: 13px; }
.picker-offset { font-size: 12.5px; color: var(--ink-soft); font-variant-numeric: tabular-nums; }
.picker-empty { padding: 10px; color: var(--ink-faint); }
.selected-list { display: flex; flex-wrap: wrap; gap: 8px; margin: 14px 0 0; padding: 0; list-style: none; }
.selected-list li { display: inline-flex; align-items: center; gap: 7px; border: 1px solid var(--line); border-radius: 999px; padding: 5px 8px 5px 12px; background: #f5f8f9; }
.chip-name { border: 0; background: transparent; font-weight: 700; cursor: pointer; color: var(--ink); padding: 0; }
.chip-remove { border: 0; background: transparent; cursor: pointer; color: var(--ink-faint); font-size: 17px; line-height: 1; padding: 0 2px; }
.chip-remove:hover { color: #b3261e; }

.summary { background: #e9f6ee; border: 1px solid #a9d8bb; border-radius: var(--radius); padding: 14px 18px; }
.summary-line { margin: 0; font-size: 16px; }
.summary-in { color: var(--ink-soft); }
.summary-title { margin: 0 0 8px; font-weight: 700; }
.summary-list { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 8px; }
.summary-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.summary-city { font-weight: 700; min-width: 200px; }
.badges { display: inline-flex; flex-wrap: wrap; gap: 6px; }
.badge { background: var(--green); color: #fff; font-weight: 700; padding: 3px 10px; border-radius: 999px; font-size: 13.5px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.summary-warn { margin: 0; background: var(--amber-bg); border: 1px solid var(--amber-line); color: var(--amber-ink); border-radius: 7px; padding: 10px 12px; font-weight: 600; }
.summary-warn-inline { background: var(--amber-bg); border: 1px solid var(--amber-line); color: var(--amber-ink); border-radius: 6px; padding: 3px 10px; font-weight: 600; font-size: 13.5px; }
.empty { background: var(--panel); border: 1px dashed var(--line); border-radius: var(--radius); padding: 36px 20px; text-align: center; color: var(--ink-soft); }
"}

{"path":"src/styles.css","find":".empty { background: var(--panel); border: 1px dashed var(--line); border-radius: var(--radius); padding: 36px 20px; text-align: center; color: var(--ink-soft); }","replace":".empty { background: var(--panel); border: 1px dashed var(--line); border-radius: var(--radius); padding: 36px 20px; text-align: center; color: var(--ink-soft); }

.grid-wrap { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px; overflow-x: auto; }
.tz-table, .tz-table-vertical { border-collapse: separate; border-spacing: 2px; width: 100%; }
.tz-table { min-width: 1120px; table-layout: fixed; }
.tz-table .city-col { width: 190px; }
.tz-table th, .tz-table td, .tz-table-vertical th, .tz-table-vertical td { text-align: center; }
.hour-head { font-size: 11px; color: var(--ink-soft); font-weight: 700; padding: 6px 0 8px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.hour-head.now { color: var(--green-dark); }
.now-dot { display: block; font-size: 7px; line-height: 1; color: var(--green); }
.city-cell, .mobile-city-head { text-align: left !important; vertical-align: middle; padding: 8px 10px; }
.city-cell { background: #f5f8f9; border-radius: 7px; }
.ref-row .city-cell, .mobile-city-head.ref-col { background: #e9f6ee; }
.city-name { border: 0; background: transparent; padding: 0; font-weight: 800; font-size: 15px; color: var(--ink); cursor: pointer; text-align: left; }
.city-name:hover { color: var(--green-dark); text-decoration: underline; }
.ref-badge {
  display: inline-block; margin-left: 7px; vertical-align: 2px;
  background: var(--green); color: #fff; font-size: 10px; font-weight: 800; letter-spacing: 0.6px;
  padding: 2px 6px; border-radius: 4px;
}
.city-sub { display: block; color: var(--ink-soft); font-size: 12.5px; font-weight: 500; }
.city-meta { display: block; color: var(--ink-faint); font-size: 12px; font-variant-numeric: tabular-nums; font-weight: 500; }
.cell {
  padding: 10px 0; border-radius: 5px; font-size: 12px; white-space: nowrap;
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-variant-numeric: tabular-nums;
}
.cell.sleeping { background: #edf0f2; color: #9aa7b1; }
.cell.awake { background: #fff; color: var(--ink); box-shadow: inset 0 0 0 1px var(--line); }
.cell.overlap { background: var(--green); color: #fff; font-weight: 800; box-shadow: inset 0 0 0 1px var(--green-dark); }
.cell.now-col { outline: 2px solid #d99a16; outline-offset: -2px; }
.remove-cell { width: 34px; }
.remove-btn {
  border: 1px solid var(--line); background: #fff; color: var(--ink-faint); border-radius: 50%;
  width: 26px; height: 26px; line-height: 1; font-size: 16px; cursor: pointer; padding: 0;
}
.remove-btn:hover { color: #b3261e; border-color: #b3261e; }

.tz-table-vertical { table-layout: fixed; min-width: 0; }
.tz-table-vertical .hour-col { width: 62px; }
.mobile-city-head { background: #f5f8f9; border-radius: 7px; vertical-align: top; position: relative; }
.mobile-city-head .city-name { font-size: 13.5px; }
.mobile-city-head .remove-btn { margin-top: 6px; }
.mobile-hour { font-size: 12px; color: var(--ink-soft); font-variant-numeric: tabular-nums; white-space: nowrap; padding: 4px 2px; }
.now-row .mobile-hour { color: var(--green-dark); }
.tz-table-vertical .cell { padding: 8px 0; font-size: 11.5px; }

.legend {
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px 18px;
  color: var(--ink-soft); font-size: 13.5px; padding: 2px 4px 8px;
}
.legend-item { display: inline-flex; align-items: center; gap: 7px; }
.swatch { width: 16px; height: 16px; border-radius: 4px; display: inline-block; }
.swatch.overlap { background: var(--green); }
.swatch.awake { background: #fff; box-shadow: inset 0 0 0 1px var(--line); }
.swatch.sleeping { background: #edf0f2; box-shadow: inset 0 0 0 1px var(--line); }
.hint { font-weight: 800; color: var(--ink); }
.footnote { color: var(--ink-faint); font-size: 12.5px; }
@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }
@media (max-width: 767px) {
  .main { padding: 12px; }
  .topbar-inner { padding: 18px 14px 4px; }
  .mode-hint { padding: 6px 14px 14px; }
  .grid-wrap { padding: 6px; }
  .summary-city { min-width: 0; }
}
"}

