{"path":"/tmp/verify_tz.mjs","content":"// Independent check of tz math (mirrors spec, not importing app code)
function offset(tz, date=new Date()){
  const dtf=new Intl.DateTimeFormat('en-US',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
  const p={}; for(const x of dtf.formatToParts(date)) if(x.type!=='literal') p[x.type]=Number(x.value);
  const asUtc=Date.UTC(p.year,p.month-1,p.day,p.hour%24,p.minute,p.second);
  return Math.round((asUtc-Math.floor(date.getTime()/1000)*1000)/60000);
}
for(const [name,tz] of [['SF','America/Los_Angeles'],['Denpasar','Asia/Makassar'],['Geneva','Europe/Zurich'],['Mumbai','Asia/Kolkata'],['Kathmandu','Asia/Kathmandu'],['Tehran','Asia/Tehran']])
  console.log(name, offset(tz), 'minutes');
function awakeAt(mins,w,s){ if(w===s) return true; const W=w*60,S=s*60; return W<S? (mins>=W&&mins<S) : (mins>=W||mins<S); }
const ref='America/Los_Angeles', cities=['America/Los_Angeles','Asia/Makassar','Europe/Zurich'];
const ro=offset(ref);
let meeting=[];
for(let h=0;h<24;h++){ if(cities.every(tz=>{ let m=((h*60+offset(tz)-ro)%1440+1440)%1440; return awakeAt(m,7,23);})) meeting.push(h); }
console.log('DEFAULT_MEETING_HOURS', JSON.stringify(meeting));
// overnight check: wake22 sleep6 should be awake at 23 and 2, asleep at 12
console.log('OVERNIGHT', awakeAt(23*60,22,6), awakeAt(2*60,22,6), awakeAt(12*60,22,6));
// base: SF vs Denpasar, SF vs Geneva
for(const tz of ['Asia/Makassar','Europe/Zurich']){
  let hrs=[]; for(let h=0;h<24;h++){ let m1=h*60, m2=((h*60+offset(tz)-ro)%1440+1440)%1440; if(awakeAt(m1,7,23)&&awakeAt(m2,7,23)) hrs.push(h); }
  console.log('BASE',tz,JSON.stringify(hrs));
}
"}

