{"path":"/tmp/tz_check.js","content":"const page = await browser.getPage("tz9303");
await page.setViewportSize({ width: 1280, height: 900 });
await page.goto("http://127.0.0.1:9303/");
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForSelector(".desktop-grid", { timeout: 8000 });

const info = await page.evaluate(() => {
  const rows = [...document.querySelectorAll(".city-row")].map(r => r.getAttribute("data-city"));
  const overlap = document.querySelectorAll('.cell[data-state="overlap"]').length;
  const perRow = [...document.querySelectorAll(".city-row")].map(r => r.querySelectorAll('.cell[data-state="overlap"]').length);
  return {
    title: document.title,
    h1: document.querySelector("h1").textContent.trim(),
    rows, overlap, perRow,
    summary: document.querySelector(".summary").textContent.replace(/\s+/g," ").trim(),
    hint: document.querySelector(".hint").textContent.trim(),
    refBadgeNear: document.querySelector(".ref-row .city-name").textContent.trim(),
    firstRowCells: [...document.querySelectorAll(".city-row")[0].querySelectorAll(".cell")].slice(0,24).map(c=>c.textContent.trim()),
    layout: document.querySelector(".grid-wrap").getAttribute("data-layout"),
  };
});
console.log("DEFAULT " + JSON.stringify(info));

// Base mode
await page.getByRole("button", { name: "Base Mode" }).click();
await page.waitForTimeout(300);
const base = await page.evaluate(() => ({
  summary: document.querySelector(".summary").textContent.replace(/\s+/g," ").trim(),
  perRow: [...document.querySelectorAll(".city-row")].map(r => r.getAttribute("data-city") + ":" + r.querySelectorAll('.cell[data-state="overlap"]').length),
  hint: document.querySelector(".hint").textContent.trim(),
}));
console.log("BASE " + JSON.stringify(base));
await page.getByRole("button", { name: "Meeting Mode" }).click();
await page.waitForTimeout(200);

// Add Tokyo via search by country "Japan"
await page.fill("#city-search", "Japan");
await page.waitForTimeout(300);
await page.locator(".picker-item").first().click();
await page.waitForTimeout(300);
const afterAdd = await page.evaluate(() => [...document.querySelectorAll(".city-row")].map(r => r.getAttribute("data-city")));
console.log("AFTER_ADD " + JSON.stringify(afterAdd));

// Promote Geneva
await page.locator('.city-row[data-city="Geneva"] .city-name').click();
await page.waitForTimeout(300);
const afterPromote = await page.evaluate(() => ({
  first: document.querySelector(".city-row").getAttribute("data-city"),
  ref: document.querySelector(".ref-row .city-name").textContent.trim(),
}));
console.log("AFTER_PROMOTE " + JSON.stringify(afterPromote));

// Change format to 24h, wake to 9
await page.getByRole("button", { name: "24h" }).click();
await page.selectOption('[aria-label="Wake-up hour"]', "9");
await page.waitForTimeout(300);
const afterSettings = await page.evaluate(() => ({
  header: [...document.querySelectorAll(".hour-head")].slice(0,4).map(c=>c.textContent.trim()),
  readout: document.querySelector(".awake-readout").textContent.replace(/\s+/g," ").trim(),
  stored: localStorage.getItem("tz-overlap-state-v1"),
}));
console.log("SETTINGS " + JSON.stringify(afterSettings));

// Persistence after reload
await page.reload();
await page.waitForSelector(".desktop-grid", { timeout: 8000 });
const persisted = await page.evaluate(() => ({
  first: document.querySelector(".city-row").getAttribute("data-city"),
  cities: [...document.querySelectorAll(".city-row")].map(r=>r.getAttribute("data-city")),
  readout: document.querySelector(".awake-readout").textContent.replace(/\s+/g," ").trim(),
}));
console.log("PERSISTED " + JSON.stringify(persisted));

// Remove Tokyo
await page.locator('[aria-label="Remove Tokyo"]').first().click();
await page.waitForTimeout(300);
const afterRemove = await page.evaluate(() => [...document.querySelectorAll(".city-row")].map(r=>r.getAttribute("data-city")));
console.log("AFTER_REMOVE " + JSON.stringify(afterRemove));

// Mobile layout
await page.setViewportSize({ width: 390, height: 800 });
await page.waitForTimeout(500);
const mobile = await page.evaluate(() => ({
  layout: document.querySelector(".grid-wrap").getAttribute("data-layout"),
  hourRows: document.querySelectorAll(".hour-row").length,
  cityCols: document.querySelectorAll(".mobile-city-head").length,
  overlap: document.querySelectorAll('.cell[data-state="overlap"]').length,
}));
console.log("MOBILE " + JSON.stringify(mobile));

// Screenshot desktop (reset to defaults for clean shot)
await page.setViewportSize({ width: 1280, height: 900 });
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForSelector(".desktop-grid", { timeout: 8000 });
const path = await saveScreenshot(await page.screenshot({ fullPage: true }), "tz-desktop.png");
console.log("SHOT " + path);
"}

