{"path":"/tmp/tz_edge.js","content":"const page = await browser.getPage("tz9303-edge");
await page.setViewportSize({ width: 1280, height: 900 });
await page.goto("http://127.0.0.1:9303/");
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForSelector(".desktop-grid", { timeout: 8000 });

// Narrow awake window 9-10 -> likely zero overlap across SF/Denpasar/Geneva
await page.selectOption('[aria-label="Wake-up hour"]', "9");
await page.selectOption('[aria-label="Sleep hour"]', "10");
await page.waitForTimeout(300);
console.log("ZERO " + JSON.stringify(await page.evaluate(() => ({
  summary: document.querySelector(".summary").textContent.replace(/\s+/g," ").trim(),
  overlap: document.querySelectorAll('.cell[data-state="overlap"]').length,
}))));

// Overnight wake 22 sleep 6
await page.selectOption('[aria-label="Wake-up hour"]', "22");
await page.selectOption('[aria-label="Sleep hour"]', "6");
await page.waitForTimeout(300);
console.log("OVERNIGHT " + JSON.stringify(await page.evaluate(() => {
  const sf = document.querySelectorAll(".city-row")[0];
  const cells = [...sf.querySelectorAll(".cell")];
  return {
    readout: document.querySelector(".awake-readout").textContent.replace(/\s+/g," ").trim(),
    sfAwakeHours: cells.map((c,i)=>c.dataset.state!=="sleeping"?i:null).filter(x=>x!==null),
  };
})));

// reset window, add Mumbai (fractional) and check cells / offset
await page.selectOption('[aria-label="Wake-up hour"]', "7");
await page.selectOption('[aria-label="Sleep hour"]', "23");
await page.fill("#city-search", "Mumbai");
await page.waitForTimeout(300);
await page.locator(".picker-item").first().click();
await page.waitForTimeout(300);
console.log("FRACTIONAL " + JSON.stringify(await page.evaluate(() => {
  const row = [...document.querySelectorAll(".city-row")].find(r=>r.dataset.city==="Mumbai");
  return {
    meta: row.querySelector(".city-meta").textContent.trim(),
    firstCells: [...row.querySelectorAll(".cell")].slice(0,4).map(c=>c.textContent.trim()),
    refCount: document.querySelectorAll(".ref-badge").length,
    cityCount: document.querySelectorAll(".city-row").length,
  };
})));

// duplicate: searching Mumbai again should offer no Mumbai item
await page.fill("#city-search", "Mumbai");
await page.waitForTimeout(300);
console.log("DUP " + JSON.stringify(await page.evaluate(() => ({
  items: [...document.querySelectorAll(".picker-item")].map(e=>e.textContent.trim()),
  empty: document.querySelector(".picker-empty") ? document.querySelector(".picker-empty").textContent.trim() : null,
}))));
console.log("DONE");
"}
